      this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/redate`, { date }, { headers: this.headers() }),
    );
  }

  /** Add a proof to a claim that is neither SETTLED nor VOID. */
  addProof(sheetId: string, id: number): Promise<Claim> {
